// همان بررسی‌ای که دیده‌بان داخلی می‌کند — از بیرون، مستقل از گیت‌هاب.
// اگر ضربان بمیرد و کرون پشتیبان هم نیاید، این تنها چشمی است که می‌بیند.
const j = $input.first().json;
const ageMin = (Date.now() - j.generated) / 60000;
const setups = j.setups || [];
const ready = setups.filter(s => !s.waiting).length;
const paper = j.paper || {};
return [{ json: {
  ageMin: Math.round(ageMin),
  stale: ageMin > 90,
  dead: ageMin > 360,
  mode: j.mode,
  reads: j.reads || 0,
  ready,
  waiting: setups.length - ready,
  balance: paper.balance,
  trades: paper.trades,
  win: paper.win_pct,
  openOrders: paper.open,
  generatedText: j.generatedText,
}}];

const j = $input.first().json;
const p = j.paper || {};
const ex = p.experiments_first_pullback || {};
const w = j.world || {};
const fg = w.fear_greed || {};
const dom = w.dominance || {};
const s = j.setups || [];
const lines = [
  '📊 *خلاصهٔ روز — ایورا لیام سیگنال*',
  '',
  `💰 دفتر کاغذی: *$${p.balance ?? '—'}* (${p.return_pct >= 0 ? '+' : ''}${p.return_pct ?? '—'}٪)`,
  `📈 ${p.trades ?? 0} معامله · برد ${p.win_pct ?? '—'}٪ · ${p.open ?? 0} باز · افت ${p.max_drawdown_pct ?? 0}٪`,
  ex.trades ? `🧪 آزمایش پولبک اول: ${ex.trades} معامله، برد ${ex.win_pct}٪` : null,
  '',
  `🎯 ستاپ‌ها الان: ${s.filter(x=>!x.waiting).length} سیگنال · ${s.filter(x=>x.waiting).length} منتظر`,
  `🌍 ترس و طمع ${fg.value ?? '—'} · دامیننس تتر ${dom.usdt ?? '—'}٪`,
  '',
  `🕐 آخرین چرخه: ${j.generatedText}`,
  '',
  '_پنل:_ auraliam18.github.io/.sognal',
].filter(Boolean);
return [{ json: { text: lines.join('\n') } }];
